// usageArgs wraps a Cobra arg-count validator so its failure is a typed
// usageError rather than an untyped message exitCode would have to sniff.
func usageArgs(validate cobra.PositionalArgs) cobra.PositionalArgs {
	return func(cmd *cobra.Command, args []string) error {
		if err := validate(cmd, args); err != nil {
			return &usageError{err: err}
		}
		return nil
	}
}

// isCobraUsageError detects the two Cobra-generated errors that carry no
// typed marker and cannot be intercepted: unknown commands and unknown
// flags on the root (root flag parsing precedes PersistentPreRun, where
// the FlagErrorFunc wrapping is installed).
func isCobraUsageError(err error) bool {
	msg := err.Error()
	prefixes := []string{
		"unknown command",
		"unknown flag",
		"unknown shorthand flag",
	}
	for _, p := range prefixes {
		if strings.HasPrefix(msg, p) {
			return true
		}
	}
	return false
}

