// flag error it can fail with a typed usageError (exit 2). It must run in
// PersistentPreRunE: SetFlagErrorFunc is not inherited, so no single init
// covers commands registered after it — but by the time this fires the
// full command tree exists.
func installFlagErrorFunc(cmd *cobra.Command) {
	for c := cmd; c != nil; c = c.Parent() {
		c.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
			return &usageError{err: err}
		})
	}
}

