func Execute() error {
	if err := rootCmd.Execute(); err != nil {
		// Cobra generates its own untyped errors for bad flags, missing
		// required flags, and failed arg validators before RunE ever runs.
		// RunE functions return typed usageErrors themselves, so wrapping
		// everything that comes back untyped cannot misclassify a runtime
		// failure: a runtime error from RunE is wrapped with fmt.Errorf and
		// would only land here if the command returned it raw, which the
		// command tests (exitCode = 2 on usage, 1 on runtime) pin down.
		if !isTyped(err) {
			err = &usageError{err: err}
		}
		fmt.Fprintln(rootCmd.ErrOrStderr(), "error:", err)
		return err
	}
	return nil
}

// isTyped reports whether the error already carries a typed marker that
// exitCode matches on. Errors that do are left alone by Execute's wrapping.
