package main

import "github.com/spf13/cobra"

// usageRunE wraps a command's RunE so every failure cobra reports before
// RunE runs — unknown flags, missing required flags, failed flag groups —
// is a typed usageError (exit 2). Arg validators get the same treatment
// from usageArgs, so by the time RunE's own return value is seen it is
// already typed: the command wrote it.
