// usageArgs wraps a Cobra arg-count validator so its failure is a typed
// usageError rather than an untyped message exitCode would have to sniff.
// The returned validator marks its own error and refuses to wrap again, so
// it stays a no-op if it is ever applied twice (test-global cobra state
// makes double-wrapping hard to rule out statically).
var errArgsWrapped = errors.New("args already validated")

func usageArgs(validate cobra.PositionalArgs) cobra.PositionalArgs {
	return func(cmd *cobra.Command, args []string) error {
		if err := validate(cmd, args); err != nil {
			var ue *usageError
			if errors.As(err, &ue) || errors.Is(err, errArgsWrapped) {
				return err
			}
			return &usageError{err: err}
		}
		return nil
	}
}

