// wrap.go rewrites cobra command literals: wraps RunE func literals in
// usageRunE(...) and Args validators in usageArgs(...).
package main

import (
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
)

func main() {
	dir := "cmd/intropy"
	entries, err := os.ReadDir(dir)
	if err != nil {
		panic(err)
	}
	for _, e := range entries {
		if filepath.Ext(e.Name()) != ".go" || filepath.Base(e.Name()) == "rune.go" {
			continue
		}
		path := filepath.Join(dir, e.Name())
		if err := process(path); err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", path, err)
		}
	}
}

func process(path string) error {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
	if err != nil {
		return err
	}
	changed := false
	ast.Inspect(f, func(n ast.Node) bool {
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		for _, elt := range cl.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			key, ok := kv.Key.(*ast.Ident)
			if !ok {
				continue
			}
			switch key.Name {
			case "RunE":
				if fl, ok := kv.Value.(*ast.FuncLit); ok {
					kv.Value = &ast.CallExpr{
						Fun:  ast.NewIdent("usageRunE"),
						Args: []ast.Expr{fl},
					}
					changed = true
				}
			case "Args":
				if ce, ok := kv.Value.(*ast.CallExpr); ok {
					if se, ok := ce.Fun.(*ast.SelectorExpr); ok {
						if pkg, ok := se.X.(*ast.Ident); ok && pkg.Name == "cobra" {
							kv.Value = &ast.CallExpr{
								Fun:  ast.NewIdent("usageArgs"),
								Args: []ast.Expr{ce},
							}
							changed = true
						}
					}
				}
			}
		}
		return true
	})
	if !changed {
		return nil
	}
	out, err := os.Create(path)
	if err != nil {
		return err
	}
	defer out.Close()
	return format.Node(out, fset, f)
}
EOF
