content.text:
package main

import "github.com/spf13/cobra"

// usageRunE wraps a command's RunE so every failure cobra reports around
// it — unknown flags, missing required flags, failed flag groups — is a
// typed usageError (exit 2). Arg validators get the same treatment from
// usageArgs, so by the time RunE's own return value is seen it is already
// typed: the command wrote it.
//
// SetFlagErrorFunc covers parse-time flag errors; required-flag and
// flag-group validation returns untyped errors straight from cobra's
// execute, so they are wrapped here before RunE runs. Both are needed
// because no single hook cobra exposes fires before all three.
func usageRunE(run func(cmd *cobra.Command, args []string) error) func(cmd *cobra.Command, args []string) error {
	return func(cmd *cobra.Command, args []string) error {
		cmd.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
			return &usageError{err: err}
		})
		if err := cmd.ValidateRequiredFlags(); err != nil {
			return &usageError{err: err}
		}
		if err := cmd.ValidateFlagGroups(); err != nil {
			return &usageError{err: err}
		}
		return run(cmd, args)
	}
}

// rootPreRun is the root command's PersistentPreRunE, named so a subcommand
// with its own pre-run can invoke it rather than silently shadowing it.
func rootPreRun(cmd *cobra.Command, args []string) error {
	if err := chdirIfRequested(); err != nil {
		return err
	}
	warnIfPreview(cmd)
	return nil
}

