// SetFlagErrorFunc covers parse-time flag errors; required-flag and
// flag-group validation returns untyped errors straight from cobra's
// execute, so they are wrapped in PreRunE — the last hook cobra fires
// before that validation. Both are needed because no single hook cobra
// exposes fires before all three.
func usageRunE(run func(cmd *cobra.Command, args []string) error) func(cmd *cobra.Command, args []string) error {
	return func(cmd *cobra.Command, args []string) error {
		cmd.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
			return &usageError{err: err}
		})
		preRun := cmd.PreRunE
		cmd.PreRunE = func(c *cobra.Command, a []string) error {
			if preRun != nil {
				if err := preRun(c, a); err != nil {
					return err
				}
			}
			if err := c.ValidateRequiredFlags(); err != nil {
				return &usageError{err: err}
			}
			if err := c.ValidateFlagGroups(); err != nil {
				return &usageError{err: err}
			}
			return nil
		}
		return run(cmd, args)
	}
}

