package main

import "github.com/spf13/cobra"

// installUsageWrap makes every failure cobra reports around RunE — unknown
// flags, missing required flags, failed flag groups — a typed usageError
// (exit 2). It must run from the root's PersistentPreRunE: that is the only
// hook cobra fires after the command is resolved but before flag parsing
// and required-flag validation. SetFlagErrorFunc covers parse-time flag
// errors; PreRunE covers the validation cobra runs between the hooks.
// Arg validators get the same treatment from usageArgs, so by the time
// RunE's own return value is seen it is already typed: the command wrote it.
func installUsageWrap(cmd *cobra.Command) {
	for c := cmd; c != nil; c = c.Parent() {
		c.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
			return &usageError{err: err}
		})
	}
	preRun := cmd.PreRunE
	cmd.PreRunE = func(c *cobra.Command, a []string) error {
		if preRun != nil {
			if err := preRun(c, a); err != nil {
				return err
			}
		}
		if err := c.ValidateRequiredFlags(); err != nil {
			return &usageError{err: err}
		}
		if err := c.ValidateFlagGroups(); err != nil {
			return &usageError{err: err}
		}
		return nil
	}
}

// rootPreRun is the root command's PersistentPreRunE, named so a subcommand
// with its own pre-run can invoke it rather than silently shadowing it.
func rootPreRun(cmd *cobra.Command, args []string) error {
	installUsageWrap(cmd)
	if err := chdirIfRequested(); err != nil {
		return err
	}
	warnIfPreview(cmd)
	return nil
}

